-- Builtin tool schemas, defaults and role bindings.
-- Kept independently from user edits so reset is exact and repeatable.
CREATE TABLE tool_defaults(key TEXT PRIMARY KEY,description TEXT NOT NULL,schema JSONB NOT NULL,agents JSONB NOT NULL);
INSERT INTO tool_defaults VALUES
('graph_overview','(Explore link diagram)Exploration Situation Distillation Summary: Asset Counting, Interfaceless Sites、frontier、Discovery、hints(Human/Main agent strategic tips to include when generating intent)。Adjust it first when planning。','{"properties": {}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('list_findings','List [confirmed vulnerabilities for this task and directly related tasks】(Compact：id+task_id+intent_id+vulnclass+severity+Abstract+Status)。Associated task entry band source_task_id/inherited=true and read-only. Only loopholes are included here; for general exploration purposes list_facts，For details node_detail(id)。','{"properties": {}, "type": "object"}'::jsonb,'["mainagent", "planner", "worker", "pentest"]'::jsonb),
('list_facts','Paginated list of [Exploration facts for this task and directly related tasks/Conclusion], latest first(Compact：id+Abstract+status, the abstract will be truncated if it is too long, use the full text node_detail(id))。All parameters are optional：limit(Default 20，Upper limit 100)、before(Cursor, returned by passing the previous page next_before Take an older page; omit/0=Latest page)、q(Filter by summary keywords)。Back {facts, total, has_more, next_before}：total is the total number after filtering，has_more=true Used when next_before Continue turning pages. Associated task entry band source_task_id/inherited=true and read-only. Look at the loopholes list_findings。','{"properties": {"before": {"description": "\u5206\u9875\u6e38\u6807\uff1a\u53ea\u8fd4\u56de id \u5c0f\u4e8e\u8be5\u503c\u7684\u66f4\u65e7\u4e8b\u5b9e\uff1b\u7701\u7565\u6216 0 = \u6700\u65b0\u4e00\u9875", "type": "integer"}, "limit": {"description": "\u8fd4\u56de\u6761\u6570\uff0c\u9ed8\u8ba4 20\uff0c\u4e0a\u9650 100", "type": "integer"}, "q": {"description": "\u6309\u4e8b\u5b9e\u6458\u8981\u5173\u952e\u8bcd\u8fc7\u6ee4\uff08\u4e0d\u533a\u5206\u5927\u5c0f\u5199\uff09\uff1b\u7701\u7565 = \u4e0d\u8fc7\u6ee4", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('node_detail','Press id Get the complete content of the [Exploration Graph Node] of this task or the directly related task. Inherit node band source_task_id/inherited=true and read-only. only list_facts/list_findings/graph_overview Returned exploration node id；Asset please use list_assets/asset_neighbors。','{"properties": {"id": {"description": "\u63a2\u7d22\u56fe\u8282\u70b9 id(\u975e\u8d44\u4ea7 id)", "type": "integer"}}, "required": ["id"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker"]'::jsonb),
('expand_digest','Expand a cold digest：Returns a compact list of its collapsed members（id/summary/state/confidence），and Overview recent_facts/recent_done_intents Same shape. Want some complete details/For evidence node_detail(member_id)。','{"properties": {"id": {"description": "digest \u8282\u70b9 id\uff08\u6765\u81ea\u6982\u89c8 cold_digests\uff09", "type": "integer"}}, "required": ["id"], "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('get_worker_output','Get this task or directly associate an intention of the task The final output conclusion of(work). Associated task results band source_task_id/inherited=true and read-only. End normally returns its summary; terminated(stopped)/Abnormal work Returns its last output up to the time of abort。','{"properties": {"intent_id": {"description": "\u610f\u56fe id\uff08= work \u53e5\u67c4\uff09", "type": "integer"}}, "required": ["intent_id"], "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('get_worker_trace','View an intent(work)’s [execution process] (different from get_worker_output Only final conclusion is given). Three ways to use：
① Transmit only intent_id → Return to this work Summary flow for each step（summary≤100word, incl. step_id；Only action outline, does not include complete output）；
② intent_id + q → Only return the summary of steps that hit the keyword (search in both summary and complete output; still only give summary，Depends on the content.③）；
③ intent_id + step_ids → Return the complete content of these steps(detail)；Maximum fetch at one time 5 , if exceeded, only the previous one will be returned 5 All are in notice/omitted_step_ids Notify you of uncollected items。
Typical process: first①/②Locating suspicious steps step_id，Reuse③Take its complete output. without thinking(thinking)Steps. Supports direct association with task history trace；The result is source_task_id/inherited=true and read only。','{"properties": {"intent_id": {"description": "\u610f\u56fe id\uff08= work \u53e5\u67c4\uff09", "type": "integer"}, "limit": {"description": "\u6458\u8981\u6d41/\u68c0\u7d22\u7684\u8fd4\u56de\u4e0a\u9650\uff08\u53ef\u9009\uff09", "type": "integer"}, "q": {"description": "\u5173\u952e\u5b57\uff1a\u53ea\u8fd4\u56de\u6458\u8981/\u5b8c\u6574\u8f93\u51fa\u547d\u4e2d\u5b83\u7684\u6b65\u9aa4\uff08\u53ef\u9009\uff1b\u4e0e step_ids \u4e92\u65a5\uff09", "type": "string"}, "step_ids": {"description": "\u8981\u53d6\u5b8c\u6574\u5185\u5bb9\u7684 step_id\uff08\u6765\u81ea\u2460/\u2461\u8fd4\u56de\uff1b\u4e00\u6b21\u6700\u591a\u53d6 5 \u4e2a\uff0c\u591a\u4f20\u53ea\u8fd4\u56de\u524d 5 \u4e2a\uff0c\u5176\u4f59\u5728 omitted_step_ids \u91cc\u5217\u51fa\uff09", "items": {"type": "integer"}, "type": "array"}}, "required": ["intent_id"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker"]'::jsonb),
('search_all_worker_traces','【It is usually not recommended because most of the information has been given in the system] in [Others of this task] work Execution Process] Click the keyword(q)Search - used to retrieve a certain worker Saw it, but didn’t write it down fact something (a certain path/token/error, etc.). Your own steps for this intention (those already in your context) are automatically excluded. Return only a summary of hit steps(summary≤100word)，Each strip intent_id；Reuse accordingly get_worker_trace(intent_id, step_ids=[...]) Get complete content。','{"properties": {"limit": {"description": "\u8fd4\u56de\u4e0a\u9650\uff0c\u9ed8\u8ba4 100\uff08\u53ef\u9009\uff09", "type": "integer"}, "q": {"description": "\u5173\u952e\u5b57\uff08\u5728\u6240\u6709 work \u6b65\u9aa4\u7684\u6458\u8981+\u5b8c\u6574\u8f93\u51fa\u91cc\u641c\uff09", "type": "string"}}, "required": ["q"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker"]'::jsonb),
('add_hint','Put humans The strategy tip for/Main agent is attached to the exploration graph and planners will read it the next time they generate an intent.。
★Priority batch: put multiple prompts in hints The array is submitted once (saving a round trip than calling one by one). Return ids Array, with hints Equal length and same order (failure item id=0，See details errors）。Omit if single item hints Directly to the top level text。','{"properties": {"asset_ids": {"description": "\u951a\u5b9a\u7684\u8d44\u4ea7 id\uff08\u53ef\u9009\uff0c0/1/\u591a\u4e2a\uff09", "items": {"type": "integer"}, "type": "array"}, "hints": {"description": "\u3010\u4f18\u5148\u7528\u8fd9\u4e2a\u3011\u8981\u65b0\u589e\u7684\u63d0\u793a\u6570\u7ec4\uff0c\u6309\u987a\u5e8f\u5904\u7406\u3002\u6bcf\u4e2a\u5143\u7d20\u5b57\u6bb5\u540c\u4e0b\u65b9\u9876\u5c42\u5b57\u6bb5\uff08text/asset_ids/traffic_refs\uff09\u3002\u8fd4\u56de ids \u4e0e\u672c\u6570\u7ec4\u7b49\u957f\u3001\u540c\u5e8f\u3002", "items": {"properties": {"asset_ids": {"items": {"type": "integer"}, "type": "array"}, "text": {"description": "\u63d0\u793a\u5185\u5bb9", "type": "string"}, "traffic_refs": {"description": "\u53ef\u9009\uff1a\u5df2\u6838\u5b9e\u4e14\u5bf9\u5e94\u672c\u63d0\u793a\u4e2d\u5177\u4f53\u6f0f\u6d1e\u7684\u6d41\u91cf\u5f15\u7528\uff0c\u4fdd\u7559\u987a\u5e8f\uff1b\u4ea4\u63a5\u540e report_finding \u53ef\u4f20 evidence_hint_id \u643a\u5e26\u8fd9\u4e9b\u5f15\u7528\u3002", "items": {"properties": {"note": {"description": "\u8be5\u6d41\u91cf\u652f\u6301\u4ec0\u4e48\u7ed3\u8bba", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "\u771f\u5b9e\u6d41\u91cf ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "type": "object"}, "type": "array"}, "text": {"description": "[\u5355\u6761] \u63d0\u793a\u5185\u5bb9\uff0c\u5982''\u91cd\u70b9\u6316\u8ba4\u8bc1\u540e\u63a5\u53e3''", "type": "string"}, "traffic_refs": {"description": "\u53ef\u9009\uff1a\u5df2\u6838\u5b9e\u4e14\u5bf9\u5e94\u672c\u63d0\u793a\u4e2d\u5177\u4f53\u6f0f\u6d1e\u7684\u6d41\u91cf\u5f15\u7528\uff0c\u4fdd\u7559\u987a\u5e8f\uff1b\u4ea4\u63a5\u540e report_finding \u53ef\u4f20 evidence_hint_id \u643a\u5e26\u8fd9\u4e9b\u5f15\u7528\u3002", "items": {"properties": {"note": {"description": "\u8be5\u6d41\u91cf\u652f\u6301\u4ec0\u4e48\u7ed3\u8bba", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "\u771f\u5b9e\u6d41\u91cf ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "type": "object"}'::jsonb,'["mainagent"]'::jsonb),
('add_intent','Generate [exploration direction] write frontier，and connect to the exploration link. Intentions are open directions for exploration, not fixed types - use summary One sentence free description to explore/Verification/What to use。
★Priority batch: multiple new directions screened out in one round are put in intents The array is submitted once (saving a round trip than calling one by one). Return ids Array, with intents Equal length and same order (failure item id=0，See details errors）。Omit if single item intents Directly to the top level summary。','{"properties": {"asset_ids": {"description": "\u672c\u65b9\u5411\u8981\u6d4b\u8bd5/\u653b\u51fb\u7684\u3010\u76ee\u6807\u8d44\u4ea7 id\u3011\uff08**\u5c3d\u91cf\u4f20**\uff0c0/1/\u591a\u4e2a\uff1b\u662f list_assets \u8fd4\u56de\u7684\u8d44\u4ea7 id\uff0c\u4e0d\u662f\u63a2\u7d22\u8282\u70b9 id\uff09\uff1a\u8fd9\u6761\u63a2\u7d22\u65b9\u5411\u9488\u5bf9\u54ea\u4e9b\u8d44\u4ea7\uff08\u7ad9\u70b9/\u63a5\u53e3/\u53c2\u6570/\u4e3b\u673a\u7b49\uff09\u3002\u53ea\u8981\u65b9\u5411\u56f4\u7ed5\u67d0\u4e9b\u5177\u4f53\u8d44\u4ea7\u5c31\u52a1\u5fc5\u4f20\u4e0a\u2014\u2014\u5b83\u662f\u300c\u8fd9\u6761\u63a2\u7d22\u6253\u54ea\u4e9b\u76ee\u6807\u300d\u7684\u7ed3\u6784\u5316\u6807\u8bb0\uff0c\u7528\u4e8e\u8986\u76d6\u53bb\u91cd\u3001\u628a\u610f\u56fe\u8fde\u5165\u8d44\u4ea7\u94fe\u8def\u3002\u4ec5\u5f53\u7eaf\u5168\u5c40\u4fa6\u5bdf\u3001\u786e\u5b9e\u6ca1\u6709\u5177\u4f53\u76ee\u6807\u8d44\u4ea7\u65f6\u624d\u7559\u7a7a\u3002", "items": {"type": "integer"}, "type": "array"}, "intents": {"description": "\u3010\u4f18\u5148\u7528\u8fd9\u4e2a\u3011\u8981\u65b0\u589e\u7684\u63a2\u7d22\u65b9\u5411\u6570\u7ec4\uff0c\u6309\u987a\u5e8f\u5904\u7406\u3002\u6bcf\u4e2a\u5143\u7d20\u5b57\u6bb5\u540c\u4e0b\u65b9\u9876\u5c42\u5b57\u6bb5\uff08summary/asset_ids/parent_ids/priority\uff09\u3002\u8fd4\u56de ids \u4e0e\u672c\u6570\u7ec4\u7b49\u957f\u3001\u540c\u5e8f\u3002", "items": {"type": "object"}, "type": "array"}, "parent_ids": {"description": "\u4e0a\u6e38\u951a\u70b9 id\uff08\u53ef\u9009\uff0c0/1/\u591a\u4e2a\uff09\uff1a\u672c\u65b9\u5411\u7531\u54ea\u4e9b\u3010\u5df2\u786e\u8ba4\u7684\u4e8b\u5b9e(fact)/\u53d1\u73b0(finding)\u3011\u7efc\u5408\u5f97\u51fa\u3002**\u53ea\u80fd\u586b\u5df2\u5b58\u5728\u7684 fact/finding \u8282\u70b9 id,\u4e0d\u80fd\u586b\u610f\u56fe/\u76ee\u6807/\u63d0\u793a**\u2014\u2014\u610f\u56fe\u5fc5\u987b\u951a\u5728\u5df2\u786e\u8ba4\u77e5\u8bc6\u4e0a,\u53d1\u73b0\u9a71\u52a8\u800c\u975e\u51ed\u7a7a\u89c4\u5212\u3002\u591a\u4e2a\u4e8b\u5b9e\u5171\u540c\u4ea7\u751f\u4e00\u4e2a\u65b0\u610f\u56fe\u5c31\u4f20\u591a\u4e2a;\u9876\u5c42\u5168\u65b0\u4fa6\u5bdf\u65b9\u5411\u8bf7\u7559\u7a7a\uff08\u4f1a\u81ea\u52a8\u6302\u5230\u4efb\u52a1\u8d77\u70b9 origin fact\uff09\u3002", "items": {"type": "integer"}, "type": "array"}, "priority": {"description": "\u4f18\u5148\u7ea7 0-10\uff0c\u9ed8\u8ba45", "type": "integer"}, "summary": {"description": "[\u5355\u6761] \u4e00\u53e5\u8bdd\u63cf\u8ff0\u8fd9\u4e2a\u63a2\u7d22\u65b9\u5411\uff1a\u505a\u4ec0\u4e48+\u4e3a\u4ec0\u4e48\u3002\u5df2\u5199\u6e05\u65b9\u5411\u5373\u53ef\uff0c\u4e0d\u4f9d\u8d56\u8d44\u4ea7 id\u3002", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('steer_work','Give a running intent(work)Inject correction instructions in real time without interrupting it or losing existing progress：worker will receive your instructions before taking the next step and adjust accordingly. used for''Don’t leave anymore X、Focus Y''This type of [intentional] correction; if the direction is completely wrong, it should be used instead kill_work Make new intentions. It is recommended to use it first get_worker_output Look what it is doing。','{"properties": {"intent_id": {"description": "\u8981\u7ea0\u504f\u7684\u610f\u56fe id\uff08= work \u53e5\u67c4\uff09", "type": "integer"}, "message": {"description": "\u7ed9 worker \u7684\u7ea0\u504f\u6307\u4ee4\uff0c\u660e\u786e\u8ba9\u5b83\u505c\u6b62\u4ec0\u4e48\u3001\u8f6c\u5411\u4ec0\u4e48", "type": "string"}}, "required": ["intent_id", "message"], "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('set_goals','Add new exploration goals to [this task](goal)。Target=Final deliverable/Verifiable results,Not an attack step or recon action。
★Priority batch:Multiple targets put in goals Array is submitted once,Back ids Same length and same order as(Failed item id=0,See details errors)。Omit if single item goals Directly to the top level text。
vulnclass Optional:Corresponding vulnerability class(Such as SQLi/IDOR),The business logic class target is left blank. Whether the goal is achieved is determined by the system. met,This tool is only responsible for adding new。','{"properties": {"goals": {"description": "\u3010\u4f18\u5148\u7528\u8fd9\u4e2a\u3011\u8981\u65b0\u589e\u7684\u76ee\u6807\u6570\u7ec4,\u6309\u987a\u5e8f\u5904\u7406\u3002\u6bcf\u4e2a\u5143\u7d20:text(\u5fc5\u586b,\u4e00\u4e2a\u72ec\u7acb\u53ef\u9a8c\u8bc1\u7684\u6700\u7ec8\u76ee\u6807)+ vulnclass(\u53ef\u9009)\u3002\u8fd4\u56de ids \u4e0e\u672c\u6570\u7ec4\u7b49\u957f\u3001\u540c\u5e8f\u3002", "items": {"type": "object"}, "type": "array"}, "text": {"description": "[\u5355\u6761] \u4e00\u4e2a\u72ec\u7acb\u53ef\u9a8c\u8bc1\u7684\u6700\u7ec8\u76ee\u6807", "type": "string"}, "vulnclass": {"description": "[\u5355\u6761] \u5bf9\u5e94\u6f0f\u6d1e\u7c7b(\u82e5\u660e\u786e),\u5982 SQLi/IDOR;\u4e1a\u52a1\u903b\u8f91\u76ee\u6807\u53ef\u7559\u7a7a", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "goals"]'::jsonb),
('set_constraints','Add operation constraints to [this task],Used to frame exploration boundaries:type=allow(Allowed operations)or deny(Prohibited operations)。
Constraints=Yes/Regulations on what operations cannot be done(If ”only test the current port,Do not scan other ports, prohibit writing to the production library, and only allow passive reconnaissance.』),Not a target, not an attack step。
★Priority batch:Put multiple items in constraints Array is submitted once,Back ids Same length and same order as(Failed item id=0,See details errors)。Omit if single item constraints Directly to the top level text/type。
Only register mission targets/[Explicitly written] constraints in the description,Don’t make things up;Used when unsure of type deny(More conservative)。','{"properties": {"constraints": {"description": "\u3010\u4f18\u5148\u7528\u8fd9\u4e2a\u3011\u8981\u65b0\u589e\u7684\u7ea6\u675f\u6570\u7ec4,\u6309\u987a\u5e8f\u5904\u7406\u3002\u6bcf\u4e2a\u5143\u7d20:text(\u5fc5\u586b,\u4e00\u6761\u7ea6\u675f)+ type(allow|deny)\u3002\u8fd4\u56de ids \u4e0e\u672c\u6570\u7ec4\u7b49\u957f\u3001\u540c\u5e8f\u3002", "items": {"type": "object"}, "type": "array"}, "text": {"description": "[\u5355\u6761] \u4e00\u6761\u64cd\u4f5c\u7ea6\u675f\u7684\u5185\u5bb9", "type": "string"}, "type": {"description": "[\u5355\u6761] allow(\u5141\u8bb8)\u6216 deny(\u7981\u6b62);\u7f3a\u7701\u6309 deny \u5904\u7406", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "goals"]'::jsonb),
('insert_assets','Batch registration of newly discovered assets, mixing multiple types at once（type See enumeration）。
